PIECES = []
_cnt = {}
def L(fx, at="mid", **kw):
    d = dict(fx=fx, at=at); d.update(kw); return d
def P(sheet, slug, title, who, slot, label, layers, dur=3.0, note="", enemy=True, cas=True, hit=0.5, sfx="hit"):
    _cnt[sheet] = _cnt.get(sheet, 0) + 1
    PIECES.append(dict(id="fx%s-%02d-%s" % (sheet, _cnt[sheet], slug), sheet=sheet, n=_cnt[sheet], slug=slug, title=title, who=who, slot=slot, label=label, layers=layers, dur=dur, note=note, enemy=enemy, cas=cas, hit=hit, sfx=sfx))

