# --- Jester (rotating acts: melee, mage, speed, ranged, defence) ---
ACTS = ["MELEE", "MAGE", "SPEED", "RANGED", "DEFENCE"]
def acts(slug, title, slot, note, fn):
    layers = []
    for i in range(5):
        t0 = i * 1.35
        layers.append(L("text", "top", t0=t0, t1=t0 + 1.3, txt=ACTS[i], s=60, font="mono", col=["a", "c", "b", "w", "b"][i], sh="#090B12", y=-10))
        layers += fn(i, t0)
    K("18", "jester", slug, title, slot, layers, dur=7.0, note=note, hit=0.3)
